     const already=t.subtasks.some(x=>String(x.title||'').trim().toLocaleLowerCase('fr')===old.toLocaleLowerCase('fr'));
     if(!already)t.subtasks.unshift({id:(crypto.randomUUID?.()||String(Date.now())+Math.random()),title:old,owner:t.assignee||t.pilot||'',due:'',done:false,migratedFromNext:true});
