function uid(){return globalThis.crypto?.randomUUID?.()||'id-'+Date.now()+'-'+Math.random().toString(36).slice(2)}
function log(obj,msg){obj.history ||= [];obj.history.push({at:new Date().toLocaleString('fr-FR'),text:msg})}
function fillDossierSelect(){ $('dossierId').innerHTML='<option value="">Action indépendante</option>'+db.dossiers.map(d=>'<option value="'+safe(d.id)+'">'+safe(d.title)+'</option>').join('') }
function dActions(d){return db.tasks.filter(t=>t.dossierId===d.id)}
function actionPct(t){let sub=t.subtasks||[];return !active(t)?100:sub.length?Math.round(100*sub.filter(x=>x.done).length/sub.length):0}
function pct(d){let tasks=dActions(d);return tasks.length?Math.round(tasks.reduce((n,t)=>n+actionPct(t),0)/tasks.length):0}
const expandedDossiers=new Set();
