 const fill=(id,vals,label)=>{let el=$(id);if(!el)return;let keep=el.value;el.innerHTML='<option value="">'+label+'</option>'+vals.map(v=>'<option value="'+safe(v)+'">'+safe(v)+'</option>').join('');el.value=vals.includes(keep)?keep:''};
